    return page(t.title,`${t.id} · ${projectName(t.project)} · ${t.release}`,`<div class="detail-grid"><div><div class="panel panel-pad">${sectionTitle('开发范围',t.issues.length,btn('调整范围','merge','small','link'))}<div class="prose"><p>明确本次要完成的事项。准备完成后，选择起始分支并开始开发。</p></div>${t.issues.map(id=>S.issues.find(i=>i.id===id)).filter(Boolean).map(i=>issueRow(i)).join('')}</div><section class="section">${sectionTitle('执行准备')}<div class="panel"><div class="setting-row"><span class="timeline-icon">${icon('check')}</span><div class="row-main"><strong>确认任务范围</strong><p>关联 ${t.issues.length} 个事项，来自 ${t.release}</p></div>${status('已确认')}</div><div class="setting-row"><span class="timeline-icon">${icon('branch')}</span><div class="row-main"><strong>准备个人环境</strong><p>${S.prepared?'个人 Git 账号与开发空间已就绪':'连接自己的 Git 账号，准备开发空间'}</p></div>${link(S.prepared?'查看环境':'准备环境','prepare','btn small')}</div><div class="setting-row"><span class="timeline-icon">${icon('play')}</span><div class="row-main"><strong>选择分支并开始</strong><p>明确提交后才启动 Agent</p></div>${link(t.status==='开发中'?'进入会话':'开始开发',t.status==='开发中'?'session':'start','btn small primary')}</div></div></section></div><aside class="detail-aside"><h3>任务信息</h3>${meta([['任务状态',status(t.status)],['执行者',avatar()+' '+h(t.owner)],['目标版本',h(t.release)],['任务来源','项目事项'],['Agent 状态',status(S.running?'运行中':'尚未开始')]])}<hr>${btn('取消任务','cancel-task','','close')}<p class="field-hint section">取消会释放当前事项的认领；正在运行的任务需先停止。</p></aside></div>`,link('返回任务','tasks','btn ghost','back'));
