  V.asset=()=>page(S.selectedAsset,'Web Console · 项目共享资料',`<div class="detail-grid"><article class="panel panel-pad prose"><h3>资料概述</h3><p>${h(S.saved.assetDescription||"这份资料记录项目相关的背景、使用方式和关键约定，便于参与者在同一上下文中协作。")}</p><h3>访问与说明</h3><p>使用项目授权的账号访问环境。受保护字段需要单独授权，只在确有需要时查看。</p>${field('环境地址','url','https://preview.example.com',{readonly:true})}<div class="field"><label>受保护字段</label><div class="toolbar"><input class="control" aria-label="受保护字段" value="${S.securityVisible?'DEMO-NOT-A-REAL-SECRET':'••••••••••••••••'}" readonly>${btn(S.securityVisible?'隐藏':'授权查看','reveal-secret','','lock')}</div><span class="field-hint">原型仅展示演示值；真实内容需后端重新鉴权。</span></div><h3>相关文件</h3>${attachment('项目参考说明.md')}</article><aside class="detail-aside"><h3>资料信息</h3>${meta([['作者',avatar()+' 林晨'],['可见范围','项目参与者'],['修订版本','3'],['更新于','今天 10:05']])}${btn('编辑资料','edit-asset','','edit')}</aside></div>`,link('返回资料库','assets','btn ghost','back'));
  V.members=()=>page('项目成员','围绕工作授权，让每位参与者都能顺畅协作。',projectTabs()+`<div class="table-wrap"><table class="list-table"><thead><tr><th>参与者</th><th>部门</th><th>当前授权</th><th></th></tr></thead><tbody>${[['林晨','linchen','协作一组','项目管理、事项、开发与交付'],['陈宇','chenyu','协作二组','事项、版本与交付'],['张敏','zhangmin','协作一组','事项、开发与资料']].map(([name,login,dept,scope])=>`<tr><td class="title-cell"><div class="row-person">${avatar(name)}${name}</div><div class="row-meta">${login}</div></td><td data-label="部门">${dept}</td><td data-label="授权">${scope}</td><td class="actions-cell">${btn('调整授权','member-permissions','small','',`data-name="${name}"`)}</td></tr>`).join('')}</tbody></table></div>`,btn('添加成员','add-member','primary','plus'));
